async (page) => {
  await page.evaluate(() => {
    window.postTitle = 'local dropoff speed + xans! dm for info!';
    window.postBody = '';
    window.postForum = 'montreal';
  });
  return "Post metadata stored in global variables";
}

async (page) => {
  const title = await page.evaluate(() => window.postTitle);
  const body = await page.evaluate(() => window.postBody);
  const forum = await page.evaluate(() => window.postForum);
  await page.fill('#submission_title', title);
  await page.fill('#submission_body', body);
  await page.selectOption('#submission_forum', { label: forum });
  await page.click('button.button');
  return "Post submitted successfully";
}
